import React, { useEffect, useRef, useState } from "react";

const Canvas = (props) => {
  const canvasRef = useRef(null);
  var [startX, setStartX] = useState(0);
  var [startY, setStartY] = useState(0);
  var [mouseState, setMouseState] = useState(-1);

  var mouseDownHandler = function (e) {
    ctx.moveTo(e.x, e.y);
    ctx.fillStyle = "white";
    setStartX(e.x);
    setStartY(e.y);
    setMouseState(0);
  };

  var mouseMoveHandler = function (e) {
    if (startX || startY === 0) {
      return;
    }
  };

  var mouseUpHandler = function (e) {
    setMouseState(2);
  };

  useEffect(() => {
    //MouseDown
    let canvas = canvasRef.current;
    let ctx = canvas.getContext("2d");
    if (mouseState == 0) {
    } else if (mouseState == 1) {
    } else if (mouseState == 2) {
      let drawX, drawY;
      if (startX < e.x) {
        drawX = startX;
      } else {
        drawX = e.x;
      }
      if (startY < e.y) {
        drawY = startY;
      } else {
        drawY = e.y;
      }
      const width = Math.abs(startX - e.x);
      const height = Math.abs(startY - e.y);
      if (props.currentTool == 1) {
        console.log("Rect drawing");
        ctx.fillStyle = "red";
        ctx.fillRect(drawX, drawY, width, height);
      }
      setStartX(0);
      setStartY(0);
    }
  }, [mouseState]);

  //   useEffect(() => {
  //     //draw on canvas
  //     let canvas = canvasRef.current;
  //     let ctx = canvas.getContext("2d");
  //     ctx.moveTo(0, 0);
  //     ctx.fillStyle = "white";
  //     ctx.fillRect(0, 0, props.width, props.height);
  //   });

  return (
    <canvas
      ref={canvasRef}
      width={props.width}
      height={props.height}
      onMouseDown={mouseDownHandler}
      onMouseMove={mouseMoveHandler}
      onMouseUp={mouseUpHandler}
    />
  );
};

export default Canvas;
